<?php
declare(strict_types=1);
if(PHP_SAPI!=='cli'){http_response_code(403);exit('Acesso reservado ao Cron.');}
require dirname(__DIR__).'/api/bootstrap.php';
require dirname(__DIR__).'/api/smtp-lib.php';
$today=(new DateTimeImmutable('today'))->format('Y-m-d');
$lastSent=$pdo->query("SELECT MAX(report_date) FROM scheduled_report_runs WHERE report_type='cheque_overview' AND status='sent'")->fetchColumn();
if($lastSent){$next=(new DateTimeImmutable((string)$lastSent))->modify('+15 days');if(new DateTimeImmutable('today')<$next)exit("Próximo relatório de cheques em ".$next->format('d/m/Y').".\n");}
$already=$pdo->prepare("SELECT COUNT(*) FROM scheduled_report_runs WHERE report_date=? AND report_type='cheque_overview' AND status='sent'");$already->execute([$today]);if((int)$already->fetchColumn()>0)exit("Relatório de cheques já enviado hoje.\n");
$rows=$pdo->query("SELECT setting_key,setting_value FROM app_settings WHERE setting_key IN ('state_processes','state_stockBikes','state_clients')")->fetchAll();$state=[];foreach($rows as $row)$state[substr($row['setting_key'],6)]=json_decode((string)$row['setting_value'],true)?:[];
$excludedInvoices=['FT2026A1/7092','FT2026A1/6302'];
$normalizeInvoice=static fn($value)=>strtoupper((string)preg_replace('/\s+/','',(string)$value));
$processes=$state['processes']??[];$bikes=array_values(array_filter($state['stockBikes']??[],static fn($bike)=>!empty($bike['chequeNumber'])&&!in_array($normalizeInvoice($bike['invoiceNumber']??''),$excludedInvoices,true)));
$e=static fn($v)=>htmlspecialchars((string)$v,ENT_QUOTES|ENT_SUBSTITUTE,'UTF-8');
$body='';foreach($bikes as $bike){$process=null;foreach($processes as $candidate)if(($candidate['id']??null)===($bike['processId']??null)){$process=$candidate;break;}$due=new DateTimeImmutable((string)$bike['chequeDueDate']);$days=(int)(new DateTimeImmutable('today'))->diff($due)->format('%r%a');$stateLabel=$due->format('Y-m-d')<$today?'Vencido':(!empty($bike['chequeCollectedEarly'])||!empty($bike['chequeCollectionTriggeredAt'])?'A vencer':'Pendente');$client=null;foreach($state['clients']??[] as $candidate)if((string)($candidate['id']??'')===(string)($bike['clientId']??'')){$client=$candidate;break;}$destination=$process?'Cliente: '.($process['client']??'').' · '.($process['id']??''):($client?'Cliente: '.($client['name']??''):'Loja / sem cliente');$body.='<tr><td><b>'.$e(($bike['brand']??'').' '.($bike['model']??'')).'</b><br><small>'.$e($bike['reference']??'').'</small></td><td>'.$e($destination).'</td><td><b>'.$e($bike['chequeNumber']).'</b></td><td>'.$e(($bike['chequeTerm']??0).' dias').'</td><td>'.$e($due->format('d/m/Y')).'</td><td><b>'.$days.'</b></td><td><b>'.$e($stateLabel).'</b></td></tr>';}
if($body==='')$body='<tr><td colspan="7">Não existem cheques registados.</td></tr>';
$html='<html><body style="font-family:Arial,sans-serif;color:#173027;background:#f4f7f5;padding:24px"><div style="max-width:1050px;margin:auto;background:white;padding:28px"><h1 style="color:#0d563e">E-Motogreen · Mapa de cheques</h1><p>Posição contabilística em '.$e((new DateTimeImmutable())->format('d/m/Y')).'.</p><table style="width:100%;border-collapse:collapse"><thead><tr style="background:#0d563e;color:white"><th>Moto / encomenda</th><th>Destino</th><th>Cheque</th><th>Prazo</th><th>Vencimento</th><th>Dias</th><th>Estado</th></tr></thead><tbody>'.$body.'</tbody></table></div></body></html>';
try{smtp_send_html($config,['contabilidade@motogreen.pt'],'E-Motogreen — Cheques pendentes — '.date('d/m/Y'),$html);$status='sent';$error=null;}catch(Throwable $exception){$status='failed';$error=$exception->getMessage();}
$log=$pdo->prepare("INSERT INTO scheduled_report_runs(report_date,report_type,status,recipients,error_message,sent_at) VALUES(?,'cheque_overview',?,'contabilidade@motogreen.pt',?,?) ON DUPLICATE KEY UPDATE status=VALUES(status),error_message=VALUES(error_message),sent_at=VALUES(sent_at)");$log->execute([$today,$status,$error,$status==='sent'?date('Y-m-d H:i:s'):null]);if($error)throw new RuntimeException($error);echo "Relatório de cheques enviado.\n";
